import{_ as s,C as a,o as l,c as d,j as e,a as c,E as o,a6 as r}from"./chunks/framework.CD0vXS2f.js";const b=JSON.parse('{"title":"01 · Executive Thesis & AI Gateway Topologies","description":"Architectural thesis, decision matrix, and multi-backend topology patterns for fronting Microsoft Foundry PTU-M and Standard deployments with Azure API Management.","frontmatter":{"title":"01 · Executive Thesis & AI Gateway Topologies","description":"Architectural thesis, decision matrix, and multi-backend topology patterns for fronting Microsoft Foundry PTU-M and Standard deployments with Azure API Management."},"headers":[],"relativePath":"playbooks/apim-gateway/01-executive-thesis.md","filePath":"playbooks/apim-gateway/01-executive-thesis.md","lastUpdated":1795642852816,"verifiedStamp":"2026-11-25 13:40 PST"}'),p={name:"playbooks/apim-gateway/01-executive-thesis.md"};function f(g,t,y,h,u,m){const i=a("PlaybookMeta"),n=a("PageBrief");return l(),d("div",null,[t[0]||(t[0]=e("h1",{id:"_01-·-executive-thesis-ai-gateway-topologies",tabindex:"-1"},[c("01 · Executive Thesis & AI Gateway Topologies "),e("a",{class:"header-anchor",href:"#_01-·-executive-thesis-ai-gateway-topologies","aria-label":'Permalink to "01 · Executive Thesis & AI Gateway Topologies"'},"​")],-1)),o(i,{track:"02 · Multi-Backend Foundry APIM AI Gateway & Governance",provenance:"Customer-Zero Validated (Multi-Practice Enterprise GenAI Gateway)",governance:"Sanitized · Peer Reviewed · IP Screened",owners:"John Luo (@jluocsa) · Co-Authors Welcome",verified:"2026-11-19 22:12 PST",status:"Live v2.0",paperHref:"/papers/enterprise-foundry-platform-blueprint",paperLabel:"Full-Stack Blueprint →",studioHref:"/studio/#apim",studioLabel:"APIM XML Policy Builder →"}),o(n,{stage:"start",readTime:"4 min read",problem:"Calling Microsoft Foundry endpoints directly from application SDKs exposes callers to PTU HTTP 429 storms, static API key sprawl, buffered SSE stalls, and broken prefix caches during spillover.",takeaway:"Centralize traffic behind an Azure API Management AI Gateway with Managed Identity RBAC, native Retry-After backend-pool circuit breakers, SKU-aware payload guards, and out-of-band FinOps telemetry.",csaUse:"Use the topology matrix below during Architecture Design Sessions to select Single-Resource, Priority Spillover Pool, or Multi-Region Active-Passive gateway patterns."}),t[1]||(t[1]=r('<h2 id="why-enterprise-foundry-platforms-require-an-ai-gateway-seam" tabindex="-1">Why Enterprise Foundry Platforms Require an AI Gateway Seam <a class="header-anchor" href="#why-enterprise-foundry-platforms-require-an-ai-gateway-seam" aria-label="Permalink to &quot;Why Enterprise Foundry Platforms Require an AI Gateway Seam&quot;">​</a></h2><p>When a single application team runs a prototype against one pay-as-you-go deployment, direct SDK retries suffice. Once multiple business units, stateless multi-node agents, and Provisioned Throughput (<code>PTU-M</code>) reservations share a central platform, <strong>four cross-cutting concerns</strong> must move out of application code and into a dedicated <strong>Azure API Management (APIM) AI Gateway</strong> <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>:</p><ol><li><strong>Deterministic PTU-to-Standard Spillover:</strong> Absorb <code>3×–6×</code> seasonal or burst traffic onto Standard PAYG only when primary <code>PTU-M</code> returns <code>429</code> or <code>5xx</code>, honoring <code>Retry-After</code> headers across all gateway workers via native backend-pool circuit breakers <span class="ev-badge ev-m">[M]</span>.</li><li><strong>SKU-Aware Wire Compatibility:</strong> Prevent HTTP <code>400</code> errors when callers emit explicit <code>prompt_cache_breakpoint</code> / <code>prompt_cache_options</code> payloads onto <strong>GPT-5.6 PTU-M</strong> (which does not support explicit breakpoints) while preserving <code>prompt_cache_key</code> across both legs <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Zero-Secret Identity &amp; Out-of-Band FinOps:</strong> Authenticate upstream to Microsoft Foundry exclusively via System/User-Assigned Managed Identity (<code>Cognitive Services OpenAI User</code>), while extracting <code>x-cost-center</code> / <code>x-practice-id</code> headers into OpenTelemetry metrics <em>before</em> forwarding so shared prefix cache keys never fragment <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Streaming-Safe <code>/responses</code> &amp; <code>/chat/completions</code> Delivery:</strong> Forward Server-Sent Events (<code>stream: true</code>) with <code>buffer-response=&quot;false&quot;</code> so time-to-first-token (TTFT) is never degraded by gateway response buffering <span class="ev-badge ev-m">[M]</span>.</li></ol>',3)),t[2]||(t[2]=e("div",{class:"arch-diagram"},[e("svg",{viewBox:"0 0 760 176",role:"img","aria-labelledby":"pb2-t1-title pb2-t1-desc","font-family":"Segoe UI, Inter, -apple-system, sans-serif"},[e("title",{id:"pb2-t1-title"},"Enterprise APIM AI Gateway Reference Flow"),e("desc",{id:"pb2-t1-desc"},"Shows Client Apps and Agent Containers calling APIM Inbound Governance (Entra JWT, Token Limit, FinOps Header Strip, SKU Body Guard), routing Priority 1 to Primary PTU-M Backend and Priority 2 Spillover on 429 Retry-After to Standard PAYG Backend, emitting OpenTelemetry token metrics."),e("defs",null,[e("marker",{id:"pb2-arr",markerWidth:"8",markerHeight:"8",refX:"7",refY:"4",orient:"auto"},[e("path",{d:"M0 0 L8 4 L0 8Z",fill:"#0f766e"})])]),e("rect",{x:"8",y:"34",width:"142",height:"98",rx:"6",fill:"#edf3fb",stroke:"#5b87b2","stroke-width":"1.4"}),e("text",{x:"16",y:"53","font-size":"9.2","font-weight":"700",fill:"#183e62"},"1. Agent & App Callers"),e("text",{x:"16",y:"69","font-size":"8.1",fill:"#334e68"},"• /openai/v1/responses"),e("text",{x:"16",y:"82","font-size":"8.1",fill:"#334e68"},"• Sharded cache_key"),e("text",{x:"16",y:"95","font-size":"8.1",fill:"#334e68"},"• Header: x-cost-center"),e("text",{x:"16",y:"116","font-size":"7.8","font-weight":"700",fill:"#1d4ed8"},"[Entra JWT / Sub Key]"),e("path",{d:"M150 83 H172",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#pb2-arr)"}),e("rect",{x:"176",y:"16",width:"212",height:"134",rx:"6",fill:"#eaf4f5",stroke:"#0f766e","stroke-width":"1.5"}),e("text",{x:"186",y:"35","font-size":"9.4","font-weight":"700",fill:"#115e59"},"2. Azure APIM AI Gateway"),e("text",{x:"186",y:"52","font-size":"8.1",fill:"#334e68"},"• Managed Identity bearer token"),e("text",{x:"186",y:"66","font-size":"8.1",fill:"#334e68"},"• azure-openai-token-limit TPM cap"),e("text",{x:"186",y:"80","font-size":"8.1",fill:"#334e68"},"• Strip x-cost-center → OTel dim"),e("text",{x:"186",y:"94","font-size":"8.1",fill:"#334e68"},"• Strip 5.6 PTU-M breakpoints"),e("text",{x:"186",y:"108","font-size":"8.1","font-weight":"700",fill:"#115e59"},"• Backend Pool Circuit Breaker"),e("text",{x:"186",y:"122","font-size":"8.1",fill:"#334e68"},'• buffer-response="false" (SSE)'),e("text",{x:"186",y:"139","font-size":"7.8","font-weight":"700",fill:"#0f766e"},"[Zero Upstream API Keys]"),e("path",{d:"M388 54 H422",stroke:"#0f766e","stroke-width":"1.9","marker-end":"url(#pb2-arr)"}),e("path",{d:"M388 114 H422",stroke:"#b45309","stroke-width":"1.7","stroke-dasharray":"4 2","marker-end":"url(#pb2-arr)"}),e("rect",{x:"426",y:"16",width:"184",height:"62",rx:"6",fill:"#eaf7f5",stroke:"#0f766e","stroke-width":"1.5"}),e("text",{x:"435",y:"34","font-size":"9.0","font-weight":"700",fill:"#115e59"},"Priority 1 · Foundry PTU-M"),e("text",{x:"435",y:"49","font-size":"8.0",fill:"#334e68"},"Steady baseline (<70% util)"),e("text",{x:"435",y:"63","font-size":"7.9","font-weight":"700",fill:"#0f766e"},"[Lowest P95 Latency & TCO]"),e("rect",{x:"426",y:"88",width:"184",height:"62",rx:"6",fill:"#fff7eb",stroke:"#d97706","stroke-width":"1.4"}),e("text",{x:"435",y:"106","font-size":"9.0","font-weight":"700",fill:"#92400e"},"Priority 2 · Standard PAYG"),e("text",{x:"435",y:"121","font-size":"8.0",fill:"#92400e"},"Spillover on 429 / 5xx"),e("text",{x:"435",y:"135","font-size":"7.9","font-weight":"700",fill:"#b45309"},"[Identical Model Snapshot]"),e("path",{d:"M610 83 H632",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#pb2-arr)"}),e("rect",{x:"636",y:"34",width:"116",height:"98",rx:"6",fill:"#edf3fb",stroke:"#5b87b2","stroke-width":"1.4"}),e("text",{x:"644",y:"53","font-size":"9.0","font-weight":"700",fill:"#183e62"},"3. App Insights"),e("text",{x:"644",y:"69","font-size":"8.0",fill:"#334e68"},"• Prompt/Completion"),e("text",{x:"644",y:"82","font-size":"8.0",fill:"#334e68"},"• Cached token %"),e("text",{x:"644",y:"95","font-size":"8.0",fill:"#334e68"},"• Spillover share"),e("text",{x:"644",y:"116","font-size":"7.8","font-weight":"700",fill:"#1d4ed8"},"[FinOps & SLOs]"),e("text",{x:"10",y:"166","font-size":"8.3",fill:"#526c80"},"Reference multi-backend AI Gateway separating caller auth/chargeback from upstream PTU-M + PAYG execution.")])],-1)),t[3]||(t[3]=r('<hr><h2 id="gateway-topology-selection-matrix" tabindex="-1">Gateway Topology Selection Matrix <a class="header-anchor" href="#gateway-topology-selection-matrix" aria-label="Permalink to &quot;Gateway Topology Selection Matrix&quot;">​</a></h2><p>Select the simplest gateway topology that satisfies your workload&#39;s capacity, residency, and isolation requirements:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Topology Pattern</th><th style="text-align:left;">How Traffic Routes</th><th style="text-align:left;">When to Choose</th><th style="text-align:left;">Limitations &amp; Guardrails</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Pattern A · Single Foundry Resource + Deployment Alias</strong></td><td style="text-align:left;">APIM routes to one Microsoft Foundry account hosting a single Standard or PTU-M deployment.</td><td style="text-align:left;">Early-stage internal tools (<code>&lt;15 RPM</code>) with single-region tolerance and non-bursty traffic.</td><td style="text-align:left;">No automatic <code>429</code> burst overflow; regional outage halts inference.</td></tr><tr><td style="text-align:left;"><strong>Pattern B · Priority Backend Pool (<code>PTU-M</code> Primary → <code>Standard</code> Spillover)</strong> <span class="ev-badge ev-arch">[Arch]</span></td><td style="text-align:left;">Native APIM Backend Pool (<code>priority: 1</code> on PTU-M, <code>priority: 2</code> on Standard PAYG in same Data Zone/region) with <code>Retry-After</code> circuit breaker <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><strong>Recommended production default</strong> for enterprise workloads with reserved baseline PTUs and seasonal/intraday bursts.</td><td style="text-align:left;">Pin the <strong>exact same model snapshot date</strong> (e.g., <code>2026-09-29</code>) on both deployments to guarantee output and rubric parity.</td></tr><tr><td style="text-align:left;"><strong>Pattern C · Multi-Account Weighted + Priority Pool</strong> <span class="ev-badge ev-arch">[Arch]</span></td><td style="text-align:left;">Priority-1 pool load-balances across multiple regional Foundry accounts (with affinity to sharded <code>prompt_cache_key</code> where supported), spilling to Priority-2 PAYG accounts.</td><td style="text-align:left;">High-scale platforms exceeding single-subscription TPM/RPM quotas or requiring active-passive regional DR (<a href="/enterprise-azure-ai-hub/playbooks/multi-region-bcp/01-executive-thesis">Playbook 03</a>).</td><td style="text-align:left;">Avoid random round-robin across distinct PTU-M accounts for the same <code>prompt_cache_key</code> shard—random fan-out dilutes per-account KV cache locality!</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Critical Cross-Playbook Rule: Cache Locality vs. Load Balancing</p><p>When two separate Microsoft Foundry accounts sit at <strong>equal priority (<code>priority: 1</code>)</strong> with 50/50 round-robin load balancing, each account maintains an <strong>independent KV prefix cache</strong> <span class="ev-badge ev-m">[M]</span>. Splitting a low-RPM prompt family across 3 active-active accounts cuts each account&#39;s Read/Write ratio by <code>3×</code>. Prefer <strong>Priority-1 single-stamp PTU-M + Priority-2 spillover</strong>, or partition traffic deterministically by practice/tenant when horizontally scaling across multiple accounts <span class="ev-badge ev-arch">[Arch]</span>.</p></div><h2 id="core-engineering-questions-answered-in-playbook-02" tabindex="-1">Core Engineering Questions Answered in Playbook 02 <a class="header-anchor" href="#core-engineering-questions-answered-in-playbook-02" aria-label="Permalink to &quot;Core Engineering Questions Answered in Playbook 02&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Question</th><th style="text-align:left;">Short Answer</th><th style="text-align:left;">Chapter</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>How do we prevent APIM from buffering SSE token streams and adding multi-second TTFT lag?</strong></td><td style="text-align:left;">Set <code>buffer-response=&quot;false&quot;</code> on <code>&lt;forward-request&gt;</code> and disable response-body transformation policies on streaming operations <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><a href="./02-capacity-streaming-limits">02 · Streaming &amp; Limits</a></td></tr><tr><td style="text-align:left;"><strong>How do native APIM backend pool circuit breakers interact with <code>429 Retry-After</code>?</strong></td><td style="text-align:left;">Configure <code>breakerRules</code> on the PTU backend for <code>429</code> and <code>500–599</code> with <code>acceptRetryAfter=&quot;true&quot;</code>, paired with <code>&lt;retry count=&quot;1&quot;&gt;</code> in <code>&lt;backend&gt;</code> so burst calls immediately route to Priority-2 PAYG <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><a href="./03-circuit-breakers-sku-rewrites">03 · Breakers &amp; SKU Rewrites</a></td></tr><tr><td style="text-align:left;"><strong>How do we bill token usage back to 5,000+ engagements without breaking shared prompt caching?</strong></td><td style="text-align:left;">Pass <code>x-cost-center</code> as an HTTP header, capture it into <code>azure-openai-emit-token-metric</code> dimensions in APIM, and strip the header before forwarding upstream <span class="ev-badge ev-arch">[Arch]</span>.</td><td style="text-align:left;"><a href="./04-finops-token-governance">04 · FinOps &amp; Quotas</a></td></tr><tr><td style="text-align:left;"><strong>How do we prove failover works before production cutover without causing client errors?</strong></td><td style="text-align:left;">Run controlled <code>429</code> fault injection and mid-stream drop tests against the <code>G1–G12</code> Gateway Readiness Standard.</td><td style="text-align:left;"><a href="./05-validation-chaos-testing">05 · Validation &amp; G1–G12</a></td></tr></tbody></table>',7))])}const w=s(p,[["render",f]]);export{b as __pageData,w as default};
